function RateConversionTool(){const[mode,setMode]=useState<"nominal-to-effective"|"effective-to-nominal">("nominal-to-effective");const[rate,setRate]=useState("12");const[frequency,setFrequency]=useState("12");const input=useMemo(()=>mode==="nominal-to-effective"?{mode,annualNominalPercent:Number(rate),compoundsPerYear:Number(frequency)}:{mode,annualEffectivePercent:Number(rate),compoundsPerYear:Number(frequency)},[mode,rate,frequency]);const output=useMemo(()=>{try{return runCalculator(rateConversionCalculator,input).output}catch{return null}},[input]);return <div className="calculator-ui"><div className="field-grid three"><label className="field"><span>Conversion</span><select value={mode} onChange={e=>setMode(e.target.value as typeof mode)}><option value="nominal-to-effective">Nominal → Effective</option><option value="effective-to-nominal">Effective → Nominal</option></select></label><NumberField label={mode==="nominal-to-effective"?"Nominal annual rate (%)":"Effective annual rate (%)"} value={rate} onChange={setRate}/><NumberField label="Compounds per year" min={1} value={frequency} onChange={setFrequency}/></div><div className="result-box" aria-live="polite"><span>{mode==="nominal-to-effective"?"Effective annual rate":"Nominal annual rate"}</span><strong>{output?`${(mode==="nominal-to-effective"?output.annualEffectivePercent:output.annualNominalPercent).toLocaleString()}%`:"Enter valid inputs"}</strong></div><CalculatorAccountActions calculatorSlug={rateConversionCalculator.slug} calculatorVersion={1} input={input} output={output}/></div>}
