function FunctionCurve({points}:{points:readonly {x:number;y:number}[]}){if(points.length<2)return null;const xs=points.map(p=>p.x),ys=points.map(p=>p.y),xmin=Math.min(...xs),xmax=Math.max(...xs),ymin=Math.min(...ys),ymax=Math.max(...ys),xr=xmax-xmin||1,yr=ymax-ymin||1;const path=points.map((p,i)=>`${i?"L":"M"} ${((p.x-xmin)/xr*100).toFixed(3)} ${(100-(p.y-ymin)/yr*100).toFixed(3)}`).join(" ");const xAxis=ymin<=0&&ymax>=0?100-(0-ymin)/yr*100:null,yAxis=xmin<=0&&xmax>=0?(0-xmin)/xr*100:null;return <div className="result-card"><h3>Function graph</h3><svg viewBox="0 0 100 100" role="img" aria-label="Function curve across the selected x range" style={{width:"100%",height:"auto",minHeight:240,overflow:"visible"}}>{xAxis!==null&&<line x1="0" x2="100" y1={xAxis} y2={xAxis} stroke="currentColor" strokeOpacity=".3" vectorEffect="non-scaling-stroke"/>}{yAxis!==null&&<line y1="0" y2="100" x1={yAxis} x2={yAxis} stroke="currentColor" strokeOpacity=".3" vectorEffect="non-scaling-stroke"/>}<path d={path} fill="none" stroke="currentColor" strokeWidth="1.5" vectorEffect="non-scaling-stroke"/></svg><p className="muted">x: {displayNumber(xmin)} to {displayNumber(xmax)} · y: {displayNumber(ymin)} to {displayNumber(ymax)}</p></div>}
