function StatisticsBatch4Tool({kind}:{kind:"regression"|"weighted"|"percentile"|"quartile"|"iqr"|"cv"|"ev"|"bayes"|"odds"}){const[values,setValues]=useState("1, 2, 3, 4"),[second,setSecond]=useState("2, 4, 6, 8"),[p,setP]=useState("75"),[q,setQ]=useState("1"),[mean,setMean]=useState("10"),[sd,setSd]=useState("2"),[probs,setProbs]=useState("0.25, 0.75"),[outcomes,setOutcomes]=useState("0, 10"),[prior,setPrior]=useState("0.2"),[like,setLike]=useState("0.8"),[alt,setAlt]=useState("0.1"),[odds,setOdds]=useState("3"),[prob,setProb]=useState("");let output:Batch4Display|null=null;try{if(kind==="regression")output=runCalculator(linearRegressionCalculator,{xValues:parseStrictNumberList(values),yValues:parseStrictNumberList(second)}).output as Batch4Display;else if(kind==="weighted")output=runCalculator(weightedMeanCalculator,{values:parseStrictNumberList(values),weights:parseStrictNumberList(second)}).output as Batch4Display;else if(kind==="percentile")output=runCalculator(percentileCalculator,{values:parseStrictNumberList(values),percentile:+p}).output as Batch4Display;else if(kind==="quartile")output=runCalculator(quartileCalculator,{values:parseStrictNumberList(values),quartileNumber:+q as 1|2|3}).output as Batch4Display;else if(kind==="iqr")output=runCalculator(interquartileRangeCalculator,{values:parseStrictNumberList(values)}).output as Batch4Display;else if(kind==="cv")output=runCalculator(coefficientOfVariationCalculator,{mean:+mean,standardDeviation:+sd}).output as Batch4Display;else if(kind==="ev")output=runCalculator(expectedValueCalculator,{outcomes:parseStrictNumberList(outcomes),probabilities:parseStrictNumberList(probs)}).output as Batch4Display;else if(kind==="bayes")output=runCalculator(bayesTheoremCalculator,{prior:+prior,likelihood:+like,evidenceGivenNot:+alt}).output as Batch4Display;else output=runCalculator(oddsCalculator,odds.trim()!==""?{odds:+odds}:{probability:+prob}).output as Batch4Display}catch{output=null}const fields=kind==="regression"?<><label className="field"><span>X values (comma-separated)</span><input value={values} onChange={e=>setValues(e.target.value)}/></label><label className="field"><span>Y values (comma-separated)</span><input value={second} onChange={e=>setSecond(e.target.value)}/></label></>:kind==="weighted"?<><label className="field"><span>Values (comma-separated)</span><input value={values} onChange={e=>setValues(e.target.value)}/></label><label className="field"><span>Positive weights (comma-separated)</span><input value={second} onChange={e=>setSecond(e.target.value)}/></label></>:kind==="percentile"?<><label className="field"><span>Values (comma-separated)</span><input value={values} onChange={e=>setValues(e.target.value)}/></label><NumberField label="Percentile (0–100)" min={0} value={p} onChange={setP}/></>:kind==="quartile"?<><label className="field"><span>Values (comma-separated)</span><input value={values} onChange={e=>setValues(e.target.value)}/></label><NumberField label="Quartile (1, 2 or 3)" min={1} value={q} onChange={setQ}/></>:kind==="iqr"?<label className="field"><span>Values (comma-separated)</span><input value={values} onChange={e=>setValues(e.target.value)}/></label>:kind==="cv"?<div className="field-grid"><NumberField label="Mean" value={mean} onChange={setMean}/><NumberField label="Standard deviation" min={0} value={sd} onChange={setSd}/></div>:kind==="ev"?<><label className="field"><span>Outcomes (comma-separated)</span><input value={outcomes} onChange={e=>setOutcomes(e.target.value)}/></label><label className="field"><span>Probabilities (comma-separated)</span><input value={probs} onChange={e=>setProbs(e.target.value)}/></label></>:kind==="bayes"?<div className="field-grid"><NumberField label="Prior P(H)" min={0} value={prior} onChange={setPrior}/><NumberField label="P(E|H)" min={0} value={like} onChange={setLike}/><NumberField label="P(E|not H)" min={0} value={alt} onChange={setAlt}/></div>:<div className="field-grid"><NumberField label="Odds" min={0} value={odds} onChange={v=>{setOdds(v);if(v!=="")setProb("")}}/><NumberField label="Probability (alternative input)" min={0} value={prob} onChange={v=>{setProb(v);if(v!=="")setOdds("")}}/></div>;const primary=kind==="regression"?["Slope",output?.slope]:kind==="weighted"?["Weighted mean",output?.weightedMean]:kind==="percentile"?["Percentile",output?.percentile]:kind==="quartile"?[`Q${output?.quartileNumber}`,output?.quartile]:kind==="iqr"?["Interquartile range",output?.interquartileRange]:kind==="cv"?["Coefficient of variation",output?.coefficientOfVariation]:kind==="ev"?["Expected value",output?.expectedValue]:kind==="bayes"?["Posterior probability",output?.posterior]:output?.direction==="probability-to-odds"?["Odds",output?.odds]:["Probability",output?.probability];return <div className="calculator-ui">{fields}{output?<><FinalResultPresentation result={{primaryResult:{id:"primary",label:primary[0] as string,value:displayNumber(primary[1] as number)},metrics:[],methodology:"Deterministic calculation using the displayed formula and supplied inputs."}}/><Steps items={output.steps}/></>:<Result value={null}/>}</div>}

