const chemistryNumericConfig:Record<ChemistryNumericKind,{slug:string;fields:readonly (readonly [string,string,string])[];label:string;unit?:string}>={moles:{slug:molesCalculator.slug,fields:[["Mass (g)","massGrams","18"],["Molar mass (g/mol)","molarMass","18"]],label:"Moles",unit:"mol"},dilution:{slug:dilutionCalculator.slug,fields:[["Initial concentration","initialConcentration","2"],["Initial volume","initialVolume","100"],["Final volume","finalVolume","200"]],label:"Final concentration"},ph:{slug:phCalculator.slug,fields:[["Hydrogen-ion concentration (mol/L)","hydrogenIonConcentration","0.0000001"]],label:"pH"},idealGas:{slug:idealGasLawCalculator.slug,fields:[["Moles","moles","1"],["Temperature (K)","temperatureKelvin","300"],["Volume (L)","volumeLiters","24.617209824288"]],label:"Pressure",unit:"atm"},gasDensity:{slug:gasDensityCalculator.slug,fields:[["Pressure (atm)","pressureAtm","1"],["Molar mass (g/mol)","molarMassGPerMol","28"],["Temperature (K)","temperatureKelvin","273.15"]],label:"Density",unit:"g/L"},percentComposition:{slug:percentCompositionCalculator.slug,fields:[["Component mass","componentMass","25"],["Total mass","totalMass","100"]],label:"Percent composition",unit:"%"},solutionConcentration:{slug:solutionConcentrationCalculator.slug,fields:[["Solute mass (g)","soluteMassGrams","10"],["Solution volume (L)","solutionVolumeLiters","2"]],label:"Concentration",unit:"g/L"},stoichiometry:{slug:stoichiometryCalculator.slug,fields:[["Known moles","knownMoles","2"],["Known coefficient","knownCoefficient","2"],["Target coefficient","targetCoefficient","1"]],label:"Target moles",unit:"mol"},halfLife:{slug:halfLifeCalculator.slug,fields:[["Initial amount","initialAmount","100"],["Elapsed time","elapsedTime","20"],["Half-life","halfLife","10"]],label:"Remaining amount"},nernst:{slug:nernstEquationCalculator.slug,fields:[["Standard potential (V)","standardPotential","1"],["Temperature (K)","temperatureKelvin","298.15"],["Electron count","electronCount","1"],["Reaction quotient","reactionQuotient","1"]],label:"Cell potential",unit:"V"},beerLambert:{slug:beerLambertLawCalculator.slug,fields:[["Molar absorptivity","molarAbsorptivity","2"],["Path length","pathLength","1"],["Concentration","concentration","0.5"]],label:"Absorbance"},titration:{slug:titrationCalculator.slug,fields:[["Titrant concentration","titrantConcentration","0.1"],["Titrant volume","titrantVolume","25"],["Analyte volume","analyteVolume","25"],["Titrant coefficient","titrantCoefficient","1"],["Analyte coefficient","analyteCoefficient","1"]],label:"Analyte concentration"}};
function runChemistryNumeric(kind:ChemistryNumericKind,input:Record<string,number>){switch(kind){case"moles":return runCalculator(molesCalculator,input as {massGrams:number;molarMass:number}).output;case"dilution":return runCalculator(dilutionCalculator,input as {initialConcentration:number;initialVolume:number;finalVolume:number}).output;case"ph":return runCalculator(phCalculator,input as {hydrogenIonConcentration:number}).output;case"idealGas":return runCalculator(idealGasLawCalculator,input as {moles:number;temperatureKelvin:number;volumeLiters:number}).output;case"gasDensity":return runCalculator(gasDensityCalculator,input as {pressureAtm:number;molarMassGPerMol:number;temperatureKelvin:number}).output;case"percentComposition":return runCalculator(percentCompositionCalculator,input as {componentMass:number;totalMass:number}).output;case"solutionConcentration":return runCalculator(solutionConcentrationCalculator,input as {soluteMassGrams:number;solutionVolumeLiters:number}).output;case"stoichiometry":return runCalculator(stoichiometryCalculator,input as {knownMoles:number;knownCoefficient:number;targetCoefficient:number}).output;case"halfLife":return runCalculator(halfLifeCalculator,input as {initialAmount:number;elapsedTime:number;halfLife:number}).output;case"nernst":return runCalculator(nernstEquationCalculator,input as {standardPotential:number;temperatureKelvin:number;electronCount:number;reactionQuotient:number}).output;case"beerLambert":return runCalculator(beerLambertLawCalculator,input as {molarAbsorptivity:number;pathLength:number;concentration:number}).output;case"titration":return runCalculator(titrationCalculator,input as {titrantConcentration:number;titrantVolume:number;analyteVolume:number;titrantCoefficient:number;analyteCoefficient:number}).output}}
function ChemistryNumericTool({kind}:{kind:ChemistryNumericKind}){const config=chemistryNumericConfig[kind];const[values,setValues]=useState(()=>config.fields.map(field=>field[2]));const input=Object.fromEntries(config.fields.map((field,index)=>[field[1],Number(values[index])]));let output:{value:number;steps:readonly string[]}|null=null;try{if(values.some(value=>value.trim()===""))throw new Error("Missing required input");output=runChemistryNumeric(kind,input)}catch{output=null}return <div className="calculator-ui"><div className="field-grid">{config.fields.map((field,index)=><NumberField key={field[1]} label={field[0]} value={values[index]} onChange={value=>setValues(current=>current.map((existing,i)=>i===index?value:existing))}/>)}</div>{output?<FinalResultPresentation result={{primaryResult:{id:"result",label:config.label,value:output.value,unit:config.unit},methodology:"Deterministic calculation using the displayed certified chemistry formula. "+output.steps.join(" ")}}/>:<div role="alert" aria-live="assertive"><Result value={null}/></div>}<CalculatorAccountActions calculatorSlug={config.slug} calculatorVersion={1} input={input} output={output}/></div>}
function MolecularWeightTool(){const[formula,setFormula]=useState("H2O");let output:{value:number;steps:readonly string[]}|null=null;try{if(!formula.trim())throw new Error("Missing formula");output=runCalculator(molecularWeightCalculator,{formula}).output}catch{output=null}return <div className="calculator-ui"><label className="field"><span>Chemical formula</span><input type="text" value={formula} onChange={event=>setFormula(event.target.value)} placeholder="e.g. H2O or Ca(OH)2"/></label>{output?<FinalResultPresentation result={{primaryResult:{id:"result",label:"Molecular weight",value:output.value,unit:"g/mol"},methodology:"Deterministic formula parsing and atomic-weight summation. "+output.steps.join(" ")}}/>:<div role="alert" aria-live="assertive"><Result value={null}/></div>}<CalculatorAccountActions calculatorSlug={molecularWeightCalculator.slug} calculatorVersion={1} input={{formula}} output={output}/></div>}

