function runEngineering(kind:EngineeringKind,input:Record<string,number>){switch(kind){case"concrete":return runCalculator(concreteCalculator,input as {lengthMeters:number;widthMeters:number;depthMeters:number;wastePercent:number}).output;case"squareFootage":return runCalculator(squareFootageCalculator,input as {lengthFeet:number;widthFeet:number;quantity:number}).output;case"paint":return runCalculator(paintCalculator,input as {wallAreaSquareMeters:number;coats:number;coverageSquareMetersPerLiter:number;wastePercent:number}).output;case"flooring":return runCalculator(flooringCalculator,input as {lengthMeters:number;widthMeters:number;wastePercent:number}).output;case"roofing":return runCalculator(roofingCalculator,input as {buildingLengthFeet:number;buildingWidthFeet:number;pitchRisePer12:number;wastePercent:number}).output;case"tile":return runCalculator(tileCalculator,input as {areaSquareMeters:number;tileLengthCm:number;tileWidthCm:number;wastePercent:number}).output;case"drywall":return runCalculator(drywallCalculator,input as {surfaceAreaSquareFeet:number;sheetLengthFeet:number;sheetWidthFeet:number;wastePercent:number}).output;case"lumber":return runCalculator(lumberCalculator,input as {thicknessInches:number;widthInches:number;lengthFeet:number;quantity:number}).output;case"stair":return runCalculator(stairCalculator,input as {totalRiseCm:number;targetRiserHeightCm:number}).output;case"fence":return runCalculator(fenceCalculator,input as {fenceLengthMeters:number;panelWidthMeters:number;wastePercent:number}).output;case"decking":return runCalculator(deckingCalculator,input as {deckAreaSquareMeters:number;boardWidthMeters:number;boardLengthMeters:number;wastePercent:number}).output;case"gravel":return runCalculator(gravelCalculator,input as {lengthMeters:number;widthMeters:number;depthMeters:number;wastePercent:number}).output;case"asphalt":return runCalculator(asphaltCalculator,input as {lengthMeters:number;widthMeters:number;depthMeters:number;densityKgPerCubicMeter:number;wastePercent:number}).output;case"excavation":return runCalculator(excavationCalculator,input as {lengthMeters:number;widthMeters:number;depthMeters:number;bulkingPercent:number}).output;case"wallpaper":return runCalculator(wallpaperCalculator,input as {wallAreaSquareMeters:number;rollCoverageSquareMeters:number;wastePercent:number}).output;case"insulation":return runCalculator(insulationCalculator,input as {areaSquareMeters:number;packCoverageSquareMeters:number;wastePercent:number}).output;case"poolVolume":return runCalculator(poolVolumeCalculator,input as {lengthMeters:number;widthMeters:number;averageDepthMeters:number}).output;case"waterTank":return runCalculator(waterTankCalculator,input as {lengthMeters:number;widthMeters:number;heightMeters:number}).output;case"pipeVolume":return runCalculator(pipeVolumeCalculator,input as {lengthMeters:number;internalDiameterMeters:number}).output;case"electricalLoad":return runCalculator(electricalLoadCalculator,input as {voltageVolts:number;currentAmps:number}).output;case"voltageDrop":return runCalculator(voltageDropCalculator,input as {currentAmps:number;oneWayLengthMeters:number;resistanceOhmsPerMeter:number;conductors:number}).output;case"resistor":return runCalculator(resistorCalculator,input as {voltageVolts:number;currentAmps:number}).output;case"hvacBtu":return runCalculator(hvacBtuCalculator,input as {floorAreaSquareMeters:number;ceilingHeightMeters:number;btuPerCubicMeter:number}).output;case"solarPanel":return runCalculator(solarPanelRequirementCalculator,input as {dailyEnergyKwh:number;panelWatts:number;peakSunHours:number;systemEfficiencyPercent:number}).output;case"batteryStorage":return runCalculator(batteryStorageCalculator,input as {dailyEnergyKwh:number;backupDays:number;depthOfDischargePercent:number;systemEfficiencyPercent:number}).output}}
function runTechnology(kind:TechnologyKind,input:Record<string,number|string>){switch(kind){case"ipSubnet":return runCalculator(ipSubnetCalculator,input as {address:string;prefixLength:number}).output;case"cidr":return runCalculator(cidrCalculator,input as {prefixLength:number}).output;case"bandwidth":return runCalculator(bandwidthCalculator,input as {dataMegabytes:number;timeSeconds:number}).output;case"downloadTime":return runCalculator(downloadTimeCalculator,input as {dataMegabytes:number;bandwidthMbps:number}).output;case"uploadTime":return runCalculator(uploadTimeCalculator,input as {dataMegabytes:number;bandwidthMbps:number}).output;case"dataTransfer":return runCalculator(dataTransferCalculator,input as {bandwidthMbps:number;timeSeconds:number}).output;case"storageConversion":return runCalculator(storageConversionCalculator,{value:Number(input.value),fromUnit:String(input.fromUnit) as "B"|"KiB"|"MiB"|"GiB"|"TiB",toUnit:String(input.toUnit) as "B"|"KiB"|"MiB"|"GiB"|"TiB"}).output;case"raidCapacity":return runCalculator(raidCapacityCalculator,{diskCount:Number(input.diskCount),diskSizeGb:Number(input.diskSizeGb),raidLevel:String(input.raidLevel) as "0"|"1"|"5"|"6"|"10"}).output;case"screenPpi":return runCalculator(screenPpiCalculator,input as {widthPixels:number;heightPixels:number;diagonalInches:number}).output;case"aspectRatio":return runCalculator(aspectRatioCalculator,input as {width:number;height:number}).output;case"resolution":return runCalculator(resolutionCalculator,input as {widthPixels:number;heightPixels:number}).output;case"dpi":return runCalculator(dpiCalculator,input as {pixels:number;lengthInches:number}).output;case"batteryRuntime":return runCalculator(batteryRuntimeCalculator,input as {capacityWh:number;loadWatts:number;efficiencyPercent:number}).output;case"upsRuntime":return runCalculator(upsRuntimeCalculator,input as {batteryWh:number;loadWatts:number;efficiencyPercent:number}).output;case"powerSupply":return runCalculator(powerSupplyCalculator,input as {systemLoadWatts:number;headroomPercent:number}).output;case"websiteBandwidth":return runCalculator(websiteBandwidthCalculator,input as {pageSizeMb:number;monthlyPageViews:number}).output;case"cloudStorageCost":return runCalculator(cloudStorageCostCalculator,input as {storageGb:number;pricePerGbMonth:number}).output;case"cloudDataTransferCost":return runCalculator(cloudDataTransferCostCalculator,input as {transferGb:number;pricePerGb:number}).output;case"base64Size":return runCalculator(base64SizeCalculator,input as {inputBytes:number}).output;case"passwordEntropy":return runCalculator(passwordEntropyCalculator,input as {length:number;characterPoolSize:number}).output}}
function TechnologyTool({kind}:{kind:TechnologyKind}){const config=technologyConfig[kind];const[values,setValues]=useState(()=>config.fields.map(f=>f[2]));const[fromUnit,setFromUnit]=useState<"B"|"KiB"|"MiB"|"GiB"|"TiB">("GiB");const[toUnit,setToUnit]=useState<"B"|"KiB"|"MiB"|"GiB"|"TiB">("MiB");const[raidLevel,setRaidLevel]=useState<"0"|"1"|"5"|"6"|"10">("10");const input:Record<string,number|string>=Object.fromEntries(config.fields.map((f,i)=>[f[1],Number(values[i])]));if(kind==="storageConversion"){input.fromUnit=fromUnit;input.toUnit=toUnit}if(kind==="raidCapacity")input.raidLevel=raidLevel;let output:{value:number;steps:readonly string[]}|null=null;try{if(values.some(v=>v.trim()===""))throw new Error("Missing required input");if(kind==="ipSubnet")input.address=values[0];output=runTechnology(kind,input)}catch{output=null}return <div className="calculator-ui"><div className="field-grid">{config.fields.map((f,i)=>kind==="ipSubnet"&&f[1]==="address"?<label className="field" key={f[1]}><span>{f[0]}</span><input type="text" inputMode="numeric" value={values[i]} onChange={e=>setValues(cur=>cur.map((x,j)=>j===i?e.target.value:x))}/></label>:<NumberField key={f[1]} label={f[0]} value={values[i]} step={["prefixLength","diskCount","widthPixels","heightPixels","monthlyPageViews","inputBytes","length","characterPoolSize"].includes(f[1])?1:undefined} onChange={v=>setValues(cur=>cur.map((x,j)=>j===i?v:x))}/>)}</div>{kind==="storageConversion"&&<div className="field-grid"><label className="field"><span>From unit</span><select value={fromUnit} onChange={e=>setFromUnit(e.target.value as typeof fromUnit)}>{["B","KiB","MiB","GiB","TiB"].map(u=><option key={u} value={u}>{u}</option>)}</select></label><label className="field"><span>To unit</span><select value={toUnit} onChange={e=>setToUnit(e.target.value as typeof toUnit)}>{["B","KiB","MiB","GiB","TiB"].map(u=><option key={u} value={u}>{u}</option>)}</select></label></div>}{kind==="raidCapacity"&&<label className="field"><span>RAID level</span><select value={raidLevel} onChange={e=>setRaidLevel(e.target.value as typeof raidLevel)}>{["0","1","5","6","10"].map(level=><option key={level} value={level}>RAID {level}</option>)}</select></label>}{output?<FinalResultPresentation result={{primaryResult:{id:"result",label:config.label,value:output.value,unit:kind==="storageConversion"?toUnit:config.unit},methodology:"Deterministic calculation using the reviewed Technology & Computing engine."}}/>:<div role="alert" aria-live="assertive"><Result value={null}/></div>}<CalculatorAccountActions calculatorSlug={config.definition.slug} calculatorVersion={config.definition.version} input={input} output={output}/></div>}
